def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, order_id, remaining_qty)
    sell_book = []  # (price, arrival_time, order_id, remaining_qty)
    order_map = {}  # order_id -> (side, index_in_book)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_idx = order_map[order_id]
                book = buy_book if side == 'buy' else sell_book
                if book_idx < len(book) and book[book_idx][2] == order_id:
                    book.pop(book_idx)
                    del order_map[order_id]
                    # Update indices for remaining orders in the book
                    for i in range(book_idx, len(book)):
                        oid = book[i][2]
                        if oid in order_map:
                            order_map[oid] = (side, i)
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            remaining_qty = qty

            if side == 'buy':
                # Match against sell_book
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_book[i] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                        if sell_book[i][3] == 0:
                            sell_book.pop(i)
                            del order_map[sell_id]
                            # Update indices for remaining orders
                            for j in range(i, len(sell_book)):
                                oid = sell_book[j][2]
                                if oid in order_map:
                                    order_map[oid] = ('sell', j)
                        else:
                            i += 1
                    else:
                        break

                # Add remaining to book if limit order
                if order_type == 'limit' and remaining_qty > 0:
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('buy', len(buy_book) - 1)
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    # Update order_map indices after sorting
                    for j, (p, a, oid, q) in enumerate(buy_book):
                        if oid in order_map:
                            order_map[oid] = ('buy', j)
            else:  # side == 'sell'
                # Match against buy_book
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_book[i] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                        if buy_book[i][3] == 0:
                            buy_book.pop(i)
                            del order_map[buy_id]
                            # Update indices for remaining orders
                            for j in range(i, len(buy_book)):
                                oid = buy_book[j][2]
                                if oid in order_map:
                                    order_map[oid] = ('buy', j)
                        else:
                            i += 1
                    else:
                        break

                # Add remaining to book if limit order
                if order_type == 'limit' and remaining_qty > 0:
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('sell', len(sell_book) - 1)
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    # Update order_map indices after sorting
                    for j, (p, a, oid, q) in enumerate(sell_book):
                        if oid in order_map:
                            order_map[oid] = ('sell', j)

            arrival_time += 1

    return trades

